 42	const matchKey = ({ description, payer, amount }) => JSON.stringify([payer, amount, description.trim().toLowerCase()])
 43	
 44	// The fields of one entry as { kind, fields }, or throws the name of the first field rule it breaks.
 45	function parseEntry(entry, group) {
 46	  if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) throw 'not-an-object'
 47	  const kind = entry.type
 48	  if (kind !== 'expense' && kind !== 'payment') throw 'bad-type'
 49	  if (Object.keys(entry).some(key => !ENTRY_FIELDS[kind].includes(key))) throw 'unknown-field'
 50	  if (kind === 'expense') {
 51	    return {
 52	      kind,
 53	      fields: {
 54	        description: check('bad-description', () => parseDescription(entry.description)),
 55	        payer: check('bad-payer', () => parseMember(entry.payer, group.members, 'bad payer')),
