102	
103	  const expenses = []
104	  const payments = []
105	  const skipped = []
106	  let nextExpenseId = state.nextExpenseId
107	  let nextPaymentId = state.nextPaymentId
108	  parsed.forEach(({ kind, fields, skipped: skip }, index) => {
109	    if (skip) skipped.push(index)
