112	  })
113	  const next = {
114	    ...state,
115	    expenses: [...state.expenses, ...expenses],
116	    payments: [...state.payments, ...payments],
117	    nextExpenseId,
118	    nextPaymentId,
119	  }
120	  const reply = {
121	    status: dryRun ? 200 : 201,
122	    body: {
123	      expenses: expenses.map(expenseView),
124	      payments: payments.map(paymentView),
125	      skipped,
126	      balances: balances(next, group),
127	    },
128	  }
129	  // A dry run, or an import whose entries were all skipped, writes nothing.
130	  if (dryRun || (expenses.length === 0 && payments.length === 0)) return reply
131	  return { ...reply, state: next }
132	}

