  1	// POST /groups/:id/import: records a list of expenses and payments in one go, all of them or none of them.
  2	// Same contract as the other handlers: it returns a new store instead of changing the one it gets.
  3	import { NOT_FOUND, findGroup } from './groups.mjs'
  4	import { balances, expenseView, paymentView } from './ledger.mjs'
  5	import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'
  6	
  7	const MAX_ENTRIES = 50
  8	const BODY_FIELDS = ['entries', 'dry_run', 'skip_recorded']
  9	const ENTRY_FIELDS = {
 10	  expense: ['type', 'description', 'payer', 'amount', 'split'],
 11	  payment: ['type', 'from', 'to', 'amount'],
 12	}
 13	
 14	const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v)
 15	
 16	// Runs parse(); on a ValidationError throws the import rule instead, so an entry stops at its first broken rule.
 17	class RuleBroken extends Error {}
 18	function check(rule, parse) {
 19	  try {
 20	    return parse()
 21	  } catch (err) {
 22	    if (err instanceof ValidationError) throw new RuleBroken(rule)
 23	    throw err
 24	  }
 25	}
 26	
 27	// Two expenses are the same when payer, amount in cents and trimmed lower-cased description match.
 28	const sameKey = ({ description, payer, amount }) => JSON.stringify([payer, amount, description.trim().toLowerCase()])
 29	
 30	function parseBody(body) {
 31	  const unknown = Object.keys(body).find(key => !BODY_FIELDS.includes(key))
 32	  if (unknown !== undefined) throw new ValidationError(`unknown field ${unknown}`)
 33	  const { entries } = body
 34	  if (!Array.isArray(entries) || entries.length < 1 || entries.length > MAX_ENTRIES) {
 35	    throw new ValidationError(`entries must be an array of 1 to ${MAX_ENTRIES} items`)
 36	  }
 37	  for (const flag of ['dry_run', 'skip_recorded']) {
 38	    if (flag in body && typeof body[flag] !== 'boolean') throw new ValidationError(`${flag} must be true or false`)
 39	  }
 40	  return { entries, dryRun: body.dry_run === true, skipRecorded: body.skip_recorded === true }
 41	}
 42	
 43	// The fields of one entry as { type, fields }, or throws RuleBroken with the first rule it breaks before the
 44	// duplicate checks.
 45	function parseEntry(group, entry) {
 46	  if (!isObject(entry)) throw new RuleBroken('not-an-object')
 47	  if (entry.type !== 'expense' && entry.type !== 'payment') throw new RuleBroken('bad-type')
 48	  if (Object.keys(entry).some(key => !ENTRY_FIELDS[entry.type].includes(key))) throw new RuleBroken('unknown-field')
 49	  if (entry.type === 'expense') {
 50	    return {
 51	      type: 'expense',
 52	      fields: {
 53	        description: check('bad-description', () => parseDescription(entry.description)),
 54	        payer: check('bad-payer', () => parseMember(entry.payer, group.members, 'payer must be a member of the group')),
 55	        amount: check('bad-amount', () => parseAmount(entry.amount)),
 56	        split: check('bad-split', () => parseSplit(entry.split, group.members)),
 57	      },
 58	    }
 59	  }
 60	  const from = check('bad-from', () => parseMember(entry.from, group.members, 'from must be a member of the group'))
 61	  const to = check('bad-to', () => parseMember(entry.to, group.members, 'to must be a member of the group'))
 62	  if (to === from) throw new RuleBroken('bad-to')
 63	  return { type: 'payment', fields: { from, to, amount: check('bad-amount', () => parseAmount(entry.amount)) } }
 64	}
 65	
 66	// Sorts the entries into new expenses and payments (with their ids), skipped indexes and problems.
 67	function sortEntries(state, group, entries, skipRecorded) {
 68	  const recorded = new Set(state.expenses.filter(e => e.group === group.id).map(sameKey))
 69	  const seen = new Set()
 70	  const problems = []
 71	  const skipped = []
 72	  const expenses = []
 73	  const payments = []
 74	  entries.forEach((entry, index) => {
 75	    let parsed
 76	    try {
 77	      parsed = parseEntry(group, entry)
 78	    } catch (err) {
 79	      if (!(err instanceof RuleBroken)) throw err
 80	      problems.push({ index, rule: err.message })
 81	      return
 82	    }
 83	    const { type, fields } = parsed
 84	    if (type === 'payment') {
 85	      payments.push({ id: state.nextPaymentId + payments.length, group: group.id, ...fields })
 86	      return
 87	    }
 88	    const key = sameKey(fields)
 89	    const isDuplicate = seen.has(key)
 90	    seen.add(key)
 91	    if (isDuplicate) problems.push({ index, rule: 'duplicate' })
 92	    else if (recorded.has(key) && skipRecorded) skipped.push(index)
 93	    else if (recorded.has(key)) problems.push({ index, rule: 'already-recorded' })
 94	    else expenses.push({ id: state.nextExpenseId + expenses.length, group: group.id, ...fields })
 95	  })
 96	  return { problems, skipped, expenses, payments }
 97	}
 98	
 99	export function importEntries({ state, params, body }) {
100	  const group = findGroup(state, params[0])
101	  if (!group) return NOT_FOUND
102	  const { entries, dryRun, skipRecorded } = parseBody(body)
103	  const { problems, skipped, expenses, payments } = sortEntries(state, group, entries, skipRecorded)
104	  if (problems.length > 0) return { status: 422, body: { error: 'import rejected', problems } }
105	
106	  const next = {
107	    ...state,
108	    expenses: [...state.expenses, ...expenses],
109	    payments: [...state.payments, ...payments],
110	    nextExpenseId: state.nextExpenseId + expenses.length,
111	    nextPaymentId: state.nextPaymentId + payments.length,
112	  }
113	  const reply = {
114	    status: dryRun ? 200 : 201,
115	    body: {
116	      expenses: expenses.map(expenseView),
117	      payments: payments.map(paymentView),
118	      skipped,
119	      balances: balances(next, group),
120	    },
121	  }
122	  // A dry run, or an import whose entries were all skipped, writes nothing.
123	  const changed = expenses.length > 0 || payments.length > 0
124	  return dryRun || !changed ? reply : { ...reply, state: next }
125	}

