 56	        split: check('bad-split', () => parseSplit(entry.split, group.members)),
 57	      },
 58	    }
 59	  }
 60	  const from = check('bad-from', () => parseMember(entry.from, group.members, 'from must be a member of the group'))
 61	  const to = check('bad-to', () => parseMember(entry.to, group.members, 'to must be a member of the group'))
 62	  if (to === from) throw new RuleBroken('bad-to')
 63	  return { type: 'payment', fields: { from, to, amount: check('bad-amount', () => parseAmount(entry.amount)) } }
 64	}
